class Solution {
  public int[] findPermutation(String s) {
    int n = s.length() + 1;
    int[] res = new int[n];
    for (int i = 0; i < n; i++) res[i] = i + 1;
    // reverse every run of 'D's (together with the number after it)
    for (int i = 0; i < s.length(); ) {
      if (s.charAt(i) == 'I') {
        i++;
        continue;
      }
      int j = i;
      while (j < s.length() && s.charAt(j) == 'D') j++;
      for (int l = i, r = j; l < r; l++, r--) {
        int t = res[l];
        res[l] = res[r];
        res[r] = t;
      }
      i = j;
    }
    return res;
  }
}
